package com.loja.checkout.pedido;

import com.loja.checkout.comum.CheckoutException;
import com.loja.checkout.comum.CodigoErro;
import java.math.BigDecimal;

/**
 * Regiao do cliente. A conta do seguro e a mesma em todas as regioes
 * (percentual sobre o valor dos produtos); so muda o percentual.
 */
public enum Regiao {

    SUDESTE("0.01"),
    SUL("0.01"),
    CENTRO_OESTE("0.015"),
    NORTE("0.025"),
    NORDESTE("0.02");

    private final BigDecimal percentualSeguro;

    Regiao(String percentualSeguro) {
        this.percentualSeguro = new BigDecimal(percentualSeguro);
    }

    public BigDecimal percentualSeguro() {
        return percentualSeguro;
    }

    public static Regiao de(String codigo) {
        for (Regiao regiao : values()) {
            if (regiao.name().equals(codigo)) {
                return regiao;
            }
        }
        throw new CheckoutException(CodigoErro.REGIAO_INVALIDA);
    }
}
EOF

cat > pedido/Pedido.java <<'EOF'
package com.loja.checkout.pedido;

import com.loja.checkout.clube.NivelClube;
import com.loja.checkout.comum.Dinheiro;
import java.math.BigDecimal;
import java.util.List;

/** O carrinho validado, com o cliente que esta comprando. */
public record Pedido(List<ItemPedido> itens, NivelClube nivelClube, Regiao regiao) {

    public Pedido {
        itens = List.copyOf(itens);
    }

    /** Soma dos produtos (preco x quantidade), arredondada para centavos. */
    public BigDecimal subtotalProdutos() {
        BigDecimal soma = itens.stream()
                .map(ItemPedido::valorTotal)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        return Dinheiro.arredondar(soma);
    }

    /** Peso do pedido: soma do peso de cada item x quantidade, sem arredondar. */
    public BigDecimal pesoTotalKg() {
        return itens.stream()
                .map(ItemPedido::pesoTotalKg)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
EOF
